var i=`0178-ribollita`;var n=`world-0178`;var a=`IT`;var o=`southern-europe`;var r=4;var s=78;var l={en:`Ribollita`,ua:`Ріболіта`};var g={en:`A classic dish from Italy, featuring yellow onion, carrot, celery stalk, cannellini beans. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: жовта цибуля, морква, стебло селери, квасоля каннеліні. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`carrot`,160,`g`],[`celery-stalk`,140,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Add the listed ingredients to the pot. Keep at a gentle simmer for about 45 minutes, until tender and cooked through.`,ua:`Додайте зазначені складники до каструлі. Варіть за слабкого кипіння приблизно 45 хвилин до м’якості та готовності.`,t:[`simmering`],m:45,i:[[`cannellini-beans`,460,`g`],[`white-cabbage`,260,`g`],[`kale`,210,`g`],[`tomato`,290,`g`],[`vegetable-stock`,1e3,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 20 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 20 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:20,i:[[`white-bread`,270,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`extra-virgin-olive-oil`,35,`ml`],[`ground-black-pepper`,null,`to_taste`]]}];var m={slug:i,id:n,country:`IT`,region:o,servings:4,minutes:78,title:l,text:g,steps:d};export{a as country,m as default,n as id,s as minutes,o as region,r as servings,i as slug,d as steps,g as text,l as title};